import { ainvoker as ai } from "ainvoker"
import { z } from "zod" 

const themeDef = ai.action.define({ 
	name: "toggle_theme", 
	direction: "Toggle theme UI to dark and light mode", 
	inputSchema: z.object({ 
		theme: z.enum(["light", "dark", "system"]) 
	}), 
	method: ({ theme }) => { 
		return setTheme(theme) 
	} 
})

const { text } = await ai.action.invoke({
	model: "openai/gpt-5.4",
	tools: [themeDef],
	prompt: "Switch theme to dark"
})

console.log(text)
